#!/bin/sh
set -eu
umask 077
python3 -I -B - <<'INSTALL_LOAD_START_R29'
import base64,hashlib,os,platform,zlib
from pathlib import Path
assert os.geteuid()==0 and platform.system()=='Linux'
raw=zlib.decompress(base64.b64decode('',validate=True))
assert len(raw)==4515 and hashlib.sha256(raw).hexdigest()=='665b2ccae784fcf1c0a53a3507f008edf8c1abbf072477ee22244ad237bd6458'
p=Path('/root/t44-r9/load-start-r29-01.py');assert p.parent.resolve()==p.parent
fd=os.open(p,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o444)
with os.fdopen(fd,'wb') as f:f.write(raw);f.flush();os.fsync(f.fileno())
print('R29_LOAD_START_WRAPPER_INSTALLED_ONLY')
INSTALL_LOAD_START_R29
